package com.codecircle.common;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.concurrent.*;import org.springframework.stereotype.*;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class RateLimitFilter extends OncePerRequestFilter {final ConcurrentHashMap<String,Window> map=new ConcurrentHashMap<>();static class Window{long at=System.currentTimeMillis();int n;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws IOException,ServletException{String ip=r.getRemoteAddr();Window w=map.computeIfAbsent(ip,x->new Window());synchronized(w){long now=System.currentTimeMillis();if(now-w.at>60000){w.at=now;w.n=0;}w.n++;if(w.n>180){s.setStatus(429);s.setContentType("application/json");s.getWriter().write("{\"message\":\"Rate limit exceeded\"}");return;}}c.doFilter(r,s);}}
